import base64
import json
import os
from typing import Any, Dict, List, Optional, Union

import requests

try:
    import azure.ai.vision.imageanalysis as imageanalysis  # type: ignore
except Exception:  # pragma: no cover
    imageanalysis = None


def _read_image_bytes(image: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)
    if isinstance(image, str):
        with open(image, "rb") as f:
            return f.read()
    raise TypeError("image must be a file path or image bytes")


def _build_analysis_result(content: Dict[str, Any], categories: List[Dict[str, Any]]) -> Dict[str, Any]:
    is_unsafe = False
    unsafe_reasons: List[str] = []

    for c in categories:
        name = (c.get("name") or c.get("category") or "").lower()
        score = c.get("score")
        if score is None:
            continue
        if name in {"adult", "racy", "gore", "violence", "sexual", "self_harm"} and float(score) >= 0.5:
            is_unsafe = True
            unsafe_reasons.append(f"{name}:{score}")

    return {
        "unsafe": is_unsafe,
        "reasons": unsafe_reasons,
        "raw": {
            "content": content,
            "categories": categories,
        },
    }


def check_image_for_unsafe_content(image: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    """
    Analyze an image for unsafe or policy-sensitive content using Azure AI Vision Image Analysis.

    Requires:
      - AZURE_VISION_ENDPOINT
      - AZURE_VISION_KEY

    Returns a dict with:
      - unsafe: bool
      - reasons: list[str]
      - raw: provider response data
    """
    endpoint = os.environ.get("AZURE_VISION_ENDPOINT")
    key = os.environ.get("AZURE_VISION_KEY")

    if not endpoint or not key:
        raise EnvironmentError("AZURE_VISION_ENDPOINT and AZURE_VISION_KEY must be set")

    image_bytes = _read_image_bytes(image)

    if imageanalysis is not None:
        # Prefer the SDK when available.
        from azure.core.credentials import AzureKeyCredential  # type: ignore

        client = imageanalysis.ImageAnalysisClient(  # type: ignore[attr-defined]
            endpoint=endpoint,
            credential=AzureKeyCredential(key),
        )

        result = client.analyze(  # type: ignore[call-arg]
            image_data=image_bytes,
            visual_features=["caption", "objects", "tags", "smartCrops", "read"],
            gender_neutral_caption=True,
            language="en",
        )

        tags = []
        if getattr(result, "tags", None):
            for t in result.tags:
                tags.append(
                    {
                        "name": getattr(t, "name", None),
                        "confidence": getattr(t, "confidence", None),
                    }
                )

        objects = []
        if getattr(result, "objects", None):
            for o in result.objects:
                objects.append(
                    {
                        "name": getattr(o, "name", None),
                        "confidence": getattr(o, "confidence", None),
                        "bounding_box": getattr(o, "bounding_box", None),
                    }
                )

        # Azure Vision Image Analysis does not expose explicit safety categories like moderation APIs.
        # Use tags/objects plus caption/read text heuristics for sensitive-content detection.
        text_lines = []
        if getattr(result, "read", None) and getattr(result.read, "blocks", None):
            for block in result.read.blocks:
                for line in getattr(block, "lines", []) or []:
                    text_lines.append(getattr(line, "text", "") or "")

        content = {
            "caption": getattr(getattr(result, "caption", None), "text", None),
            "text": text_lines,
        }

        suspicious_terms = {
            "nudity",
            "nude",
            "sexual",
            "porn",
            "explicit",
            "violence",
            "bloody",
            "blood",
            "weapon",
            "gun",
            "knife",
            "drug",
            "self-harm",
            "suicide",
            "hate",
            "terrorist",
        }

        reasons: List[str] = []
        haystack = " ".join(
            [
                str(content.get("caption") or ""),
                " ".join(text_lines),
                " ".join([t.get("name") or "" for t in tags]),
                " ".join([o.get("name") or "" for o in objects]),
            ]
        ).lower()

        for term in suspicious_terms:
            if term in haystack:
                reasons.append(term)

        return {
            "unsafe": len(reasons) > 0,
            "reasons": sorted(set(reasons)),
            "raw": {
                "caption": content["caption"],
                "text": text_lines,
                "tags": tags,
                "objects": objects,
            },
        }

    # REST fallback using Azure AI Vision Image Analysis endpoint
    url = endpoint.rstrip("/") + "/computervision/imageanalysis:analyze"
    params = {
        "api-version": "2023-02-01-preview",
        "features": "caption,tags,objects,read",
        "language": "en",
        "gender-neutral-caption": "true",
    }
    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/octet-stream",
    }
    resp = requests.post(url, params=params, headers=headers, data=image_bytes, timeout=60)
    resp.raise_for_status()
    data = resp.json()

    tags = data.get("tagsResult", {}).get("values", []) if isinstance(data, dict) else []
    objects = data.get("objectsResult", {}).get("values", []) if isinstance(data, dict) else []
    caption = None
    if isinstance(data, dict):
        caption_data = data.get("captionResult", {})
        if isinstance(caption_data, dict):
            caption = caption_data.get("text")

    text_lines = []
    read_result = data.get("readResult", {}) if isinstance(data, dict) else {}
    if isinstance(read_result, dict):
        blocks = read_result.get("blocks", []) or []
        for block in blocks:
            for line in block.get("lines", []) or []:
                if "text" in line:
                    text_lines.append(line["text"])

    content = {"caption": caption, "text": text_lines}

    suspicious_terms = {
        "nudity",
        "nude",
        "sexual",
        "porn",
        "explicit",
        "violence",
        "bloody",
        "blood",
        "weapon",
        "gun",
        "knife",
        "drug",
        "self-harm",
        "suicide",
        "hate",
        "terrorist",
    }

    reasons: List[str] = []
    haystack = " ".join(
        [
            str(caption or ""),
            " ".join(text_lines),
            " ".join([str(t.get("name", "")) for t in tags if isinstance(t, dict)]),
            " ".join([str(o.get("name", "")) for o in objects if isinstance(o, dict)]),
        ]
    ).lower()

    for term in suspicious_terms:
        if term in haystack:
            reasons.append(term)

    return {
        "unsafe": len(reasons) > 0,
        "reasons": sorted(set(reasons)),
        "raw": {
            "caption": caption,
            "text": text_lines,
            "tags": tags,
            "objects": objects,
        },
    }
